create type public.product_status as enum ('draft','published','archived');
create type public.offer_platform as enum ('tiktok_shop','amazon');
create type public.media_type as enum ('image','video','tiktok_embed');
create type public.social_platform as enum ('tiktok','instagram','youtube','pinterest','website','email');

create table public.creator_profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  handle text not null unique check (handle ~ '^[a-z0-9_]{3,40}$'),
  display_name text not null check (char_length(display_name) between 2 and 80),
  tagline text, profile_image_url text, affiliate_disclosure text not null default 'Some links are affiliate links. If you shop through them, I may earn a commission at no extra cost to you.',
  contact_email text, contact_visible boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.collections (id uuid primary key default gen_random_uuid(), creator_id uuid not null references public.creator_profiles(id) on delete cascade, slug text not null, title text not null, description text, image_url text, display_order integer not null default 0, status public.product_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(creator_id,slug));
create table public.products (id uuid primary key default gen_random_uuid(), creator_id uuid not null references public.creator_profiles(id) on delete cascade, collection_id uuid references public.collections(id) on delete set null, slug text not null, title text not null, creator_note text, tags text[] not null default '{}', status public.product_status not null default 'draft', published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(creator_id,slug));
create table public.product_offers (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, platform public.offer_platform not null default 'tiktok_shop', destination_url text not null, is_primary boolean not null default true, is_active boolean not null default true, created_at timestamptz not null default now());
create unique index one_primary_offer_per_product_platform on public.product_offers(product_id,platform) where is_primary;
create table public.product_media (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, media_type public.media_type not null, url text not null, alt_text text not null default '', display_order integer not null default 0, is_cover boolean not null default false, tiktok_post_url text, created_at timestamptz not null default now());
create unique index one_cover_per_product on public.product_media(product_id) where is_cover;
create table public.social_links (id uuid primary key default gen_random_uuid(), creator_id uuid not null references public.creator_profiles(id) on delete cascade, platform public.social_platform not null, url text not null, label text, display_order integer not null default 0, is_visible boolean not null default true, created_at timestamptz not null default now());
create table public.import_batches (id uuid primary key default gen_random_uuid(), creator_id uuid not null references public.creator_profiles(id) on delete cascade, source text not null default 'csv', created_at timestamptz not null default now());
create table public.import_rows (id uuid primary key default gen_random_uuid(), batch_id uuid not null references public.import_batches(id) on delete cascade, row_number integer not null, affiliate_url text, tiktok_post_url text, title text, collection_name text, errors jsonb not null default '[]', is_selected boolean not null default false, created_at timestamptz not null default now());
create table public.outbound_clicks (id uuid primary key default gen_random_uuid(), offer_id uuid not null references public.product_offers(id) on delete cascade, source text not null default 'direct' check (source in ('tiktok','instagram','newsletter','direct')), clicked_at timestamptz not null default now());
create index products_public_index on public.products(creator_id,status,published_at desc); create index collections_public_index on public.collections(creator_id,status,display_order); create index media_product_index on public.product_media(product_id,display_order); create index clicks_offer_date_index on public.outbound_clicks(offer_id,clicked_at desc);

alter table public.creator_profiles enable row level security; alter table public.collections enable row level security; alter table public.products enable row level security; alter table public.product_offers enable row level security; alter table public.product_media enable row level security; alter table public.social_links enable row level security; alter table public.import_batches enable row level security; alter table public.import_rows enable row level security; alter table public.outbound_clicks enable row level security;
create policy "public views published profiles" on public.creator_profiles for select using (true);
create policy "owners manage their profile" on public.creator_profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "public views published collections" on public.collections for select using (status='published' or auth.uid()=creator_id); create policy "owners manage collections" on public.collections for all using (auth.uid()=creator_id) with check (auth.uid()=creator_id);
create policy "public views published products" on public.products for select using (status='published' or auth.uid()=creator_id); create policy "owners manage products" on public.products for all using (auth.uid()=creator_id) with check (auth.uid()=creator_id);
create policy "public views active published offers" on public.product_offers for select using (is_active and exists(select 1 from public.products p where p.id=product_id and (p.status='published' or p.creator_id=auth.uid()))); create policy "owners manage offers" on public.product_offers for all using (exists(select 1 from public.products p where p.id=product_id and p.creator_id=auth.uid())) with check (exists(select 1 from public.products p where p.id=product_id and p.creator_id=auth.uid()));
create policy "public views media for published products" on public.product_media for select using (exists(select 1 from public.products p where p.id=product_id and (p.status='published' or p.creator_id=auth.uid()))); create policy "owners manage media" on public.product_media for all using (exists(select 1 from public.products p where p.id=product_id and p.creator_id=auth.uid())) with check (exists(select 1 from public.products p where p.id=product_id and p.creator_id=auth.uid()));
create policy "public views enabled social links" on public.social_links for select using (is_visible or auth.uid()=creator_id); create policy "owners manage social links" on public.social_links for all using (auth.uid()=creator_id) with check (auth.uid()=creator_id);
create policy "owners manage import batches" on public.import_batches for all using (auth.uid()=creator_id) with check (auth.uid()=creator_id); create policy "owners manage import rows" on public.import_rows for all using (exists(select 1 from public.import_batches b where b.id=batch_id and b.creator_id=auth.uid())) with check (exists(select 1 from public.import_batches b where b.id=batch_id and b.creator_id=auth.uid()));
create policy "owners view their click metrics" on public.outbound_clicks for select using (exists(select 1 from public.product_offers o join public.products p on p.id=o.product_id where o.id=offer_id and p.creator_id=auth.uid()));
